public boolean shouldPrintMessage(int timestamp, String message) {
    // Calculate the difference between the current and the provided timestamps in seconds
    long currentTimestamp = System.currentTimeMillis() / 1000;
    long difference = Math.abs(currentTimestamp - timestamp);

    // Check if the difference is less than or equal to 60 seconds
    if (difference <= 60) {
        // Print the message
        System.out.println(message);
        return true;
    } else {
        // Do not print the message
        return false;
    }
}

