public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }
    if (file.isDirectory()) {
        File[] files = file.listFiles();
        for (File subFile : files) {
            forceDeleteOnExit(subFile);
        }
    }
    if (file.delete()) {
        System.out.println("File " + file.getName() + " has been scheduled for deletion on JVM exit");
    } else {
        throw new IOException("Could not schedule file " + file.getName() + " for deletion on JVM exit");
    }
}

