public void write(final byte b[],final int off,final int len) throws IOException {
    if (b == null) {
        throw new NullPointerException();
    }
    if (off < 0 || len < 0 || off + len > b.length) {
        throw new IndexOutOfBoundsException();
    }
    if (len == 0) {
        return;
    }
    int index = off;
    int remaining = len;
    byte[] newBuffer = null;
    while (remaining > 0) {
        if (buffer == null) {
            int toCopy = Math.min(remaining, initialBufferLength);
            newBuffer = new byte[toCopy];
            System.arraycopy(b, index, newBuffer, 0, toCopy);
            buffer = newBuffer;
            index += toCopy;
            remaining -= toCopy;
        } else {
            int toCopy = Math.min(remaining, buffer.length);
            System.arraycopy(b, index, buffer, 0, toCopy);
            index += toCopy;
            remaining -= toCopy;
            if (remaining > 0) {
                newBuffer = new byte[remaining];
                System.arraycopy(b, index, newBuffer, 0, remaining);
                buffer = newBuffer;
                index += remaining;
                remaining = 0;
            }
        }
    }
}

