private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
  // Initialize a circulator to start at the start node
  OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);

  // Check if the start node satisfies the predicate
  if (predicate.test(start)) {
    // If it does, return the circulator to the start node
    return circ;
  }

  // Initialize a set to keep track of the visited nodes
  Set<Node> visited = new HashSet<>();

  // While there are no visited nodes, or the stop node has not been reached
  while (visited.isEmpty() || !visited.contains(stop)) {
    // Move the circulator to the next node in the direction of the traversal
    circ.move(dir);

    // Get the current node from the circulator
    Node current = circ.getCurrentNode();

    // If the current node satisfies the predicate, return the circulator
    if (predicate.test(current)) {
      return circ;
    }

    // Add the current node to the set of visited nodes
    visited.add(current);
  }

  // If we reach this point, it means the stop node has been reached without finding a node that satisfies the predicate
  // Return a circulator to the stop node
  return new OuterFaceCirculator(stop, dir);
}

