        if (frequency == null) {
            frequency = 0;
        }
        keyFrequencies.put(key, frequency + 1);
    }

    // Computing the lower bounds
    List<Integer> lowerBounds = new ArrayList<>();
    for (Map.Entry<K, Integer> entry : keyFrequencies.entrySet()) {
        K key = entry.getKey();
        int frequency = entry.getValue();
        lowerBounds.add(Math.max(frequency - 1, 0));
    }

    return lowerBounds;
}

