public static String unescapeJava(String str) throws IOException {
    if (str == null) {
        return null;
    }
    StringBuffer buffer = new StringBuffer();
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char ch = str.charAt(i);
        if (ch == '\\') {
            if (i + 1 < len) { // there is a next character
                char nextChar = str.charAt(i + 1);
                if (nextChar == 'n') {
                    // newline character
                    buffer.append('\n');
                    i++; // skip the next character
                } else if (nextChar == 't') {
                    // tab character
                    buffer.append('\t');
                    i++; // skip the next character
                } else if (nextChar == '\\') {
                    // backslash character
                    buffer.append('\\');
                    i++; // skip the next character
                } else if (nextChar == 'r') {
                    // return character
                    buffer.append('\r');
                    i++; // skip the next character
                } else if (nextChar == 'f') {
                    // form feed character
                    buffer.append('\f');
                    i++; // skip the next character
                } else if (nextChar == '\n') {
                    // one more newline character
                    buffer.append('\n');
                    i++; // skip the next character
                } else {
                    // unknown character, leave as is
                    buffer.append(ch);
                }
            } else {
                // last character
                buffer.append(ch);
            }
        } else {
            // not an escaped character, just append it
            buffer.append(ch);
        }
    }
    return buffer.toString();
}

