public String format(LoggingEvent event) {
    StringBuilder builder = new StringBuilder();

    // Add the date and time to the message
    builder.append(new SimpleDateFormat("yyyy-MM-dd HH:mm:ss").format(event.getTimeStamp()));
    builder.append(" ");

    // Get the log level and add it to the message
    Level level = event.getLevel();
    if (level.equals(Level.DEBUG)) {
        builder.append("DEBUG ");
    } else if (level.equals(Level.INFO)) {
        builder.append("INFO ");
    } else if (level.equals(Level.WARN)) {
        builder.append("WARN ");
    } else if (level.equals(Level.ERROR)) {
        builder.append("ERROR ");
    } else {
        builder.append("UNKNOWN ");
    }

    // Get the message and add it to the message
    String message = event.getMessage().getFormattedMessage();
    if (message != null) {
        builder.append(message);
    }

    // Get the exception and add it to the message
    Throwable throwable = event.getThrowable();
    if (throwable != null) {
        builder.append("\n");
        builder.append(throwable.toString());
    }

    return builder.toString();
}

