        // locate end of word
        int end = start + 1;
        while (end < buf.length() && isLetter(buf.charAt(end))) {
            end++;
        }
        // abbreviate word
        buf.setCharAt(start, toUpperCase(buf.charAt(start)));
        buf.delete(start + 1, end);
    }

