  // If there is no value associated with the key, set the current value to 0
  if (currentValue == null) {
    currentValue = 0L;
  }

  // Add the new value to the current value
  currentValue += value;

  // Store the updated value in the accumulator map
  accumulator.put(key, currentValue);
}

