public Mappings diffStructure(String tableName, Mappings mappings) {

    // Check if the input mappings are history mapping from current index
    if (!mappings.isHistoryMapping() || !mappings.getIndexName().equals(tableName)) {
        throw new IllegalArgumentException("Mappings should be history mapping from current index table " + tableName + " but are " + mappings.getIndexName());
    }

    // Get the current mapping from index
    Mappings currentMappings = this.mappings.getMapping(tableName);

    // Check if the input mappings are newer than the current mapping
    if (mappings.getLastUpdateTimestamp() < currentMappings.getLastUpdateTimestamp()) {
        throw new IllegalArgumentException("History mapping should be newer than current mapping but are " + mappings.getLastUpdateTimestamp());
    }

    // Create a new mapping with only fields that not exist
    Mappings newMappings = new Mappings(tableName, new LinkedHashMap<>());
    Set<String> fieldNames = currentMappings.getFieldNames();
    for (String fieldName : mappings.getFieldNames()) {
        if (!fieldNames.contains(fieldName)) {
            newMappings.put(fieldName, mappings.get(fieldName));
        }
    }

    // Return the new mapping with structures that not exist
    LOG.debug("Returning new mapping with structures that not exist {}", newMappings.getFieldNames());
    return newMappings;
}

