    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }

    // Compute the number of days to adjust the time bucket
    long numDays = timeBucket % dayStep;

    // Adjust the time bucket by the number of days
    return timeBucket - numDays;
}

