public List<SequenceRange> buildSequenceRanges() {
  // (1) Build a list of all the profile segments
  List<ProfileSegment> profileSegments = new ArrayList<>();
  for (ProfileSegment segment : getProfile().getSegments()) {
    if (segment.getEnd() > 0) {
      profileSegments.add(segment);
    }
  }

  // (2) Build a map of sequence ranges for each profile segment
  Map<ProfileSegment, List<SequenceRange>> sequenceRangeMap = new HashMap<>();
  for (ProfileSegment segment : profileSegments) {
    List<SequenceRange> sequenceRanges = new ArrayList<>();
    for (SequenceRange sequenceRange : segment.getSequenceRanges()) {
      sequenceRanges.add(sequenceRange);
    }
    sequenceRangeMap.put(segment, sequenceRanges);
  }

  // (3) Build a list of all the sequence ranges for the current profile
  List<SequenceRange> currentSequenceRanges = new ArrayList<>();
  for (int i = 0; i < profileSegments.size(); i++) {
    List<SequenceRange> sequenceRanges = sequenceRangeMap.get(profileSegments.get(i));
    for (int j = 0; j < sequenceRanges.size(); j++) {
      SequenceRange currentSequenceRange = sequenceRanges.get(j);
      if (currentSequenceRange.getStart() == getSequence().getStart() && currentSequenceRange.getEnd() == getSequence().getEnd()) {
        currentSequenceRanges.add(currentSequenceRange);
      }
    }
  }

  return currentSequenceRanges;
}

